/**
 * The lucide-react-native entry point creates all ~1,700 icon components the moment it is
 * imported, which costs startup time and ~1 MB of bundle for the 68 or so icons in use.
 *
 * Metro points `lucide-react-native` at a generated file (src/lucide-icons.generated.js) that
 * re-exports only the icons the app imports. TypeScript still sees the real package, so
 * editor typing is unchanged. metro.config.js regenerates the file on every Metro start, so a
 * new icon only needs a restart of the dev server.
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const LUCIDE_ESM = path.join(root, 'node_modules', 'lucide-react-native', 'dist', 'esm');
const OUTPUT = path.join(root, 'src', 'lucide-icons.generated.js');
const IMPORT_RE = /import\s+(type\s+)?\{([^}]*)\}\s*from\s*['"]lucide-react-native['"]/g;

function sourceFiles(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return sourceFiles(full);
    return /\.(tsx?|jsx?)$/.test(entry.name) && full !== OUTPUT ? [full] : [];
  });
}

function usedIcons() {
  const names = new Set();
  const files = [...sourceFiles(path.join(root, 'src')), path.join(root, 'App.tsx')];
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8');
    for (const [, typeOnly, list] of text.matchAll(IMPORT_RE)) {
      if (typeOnly) continue;
      for (const spec of list.split(',').map(s => s.trim()).filter(Boolean)) {
        if (!spec.startsWith('type ')) names.add(spec.split(/\s+as\s+/)[0]);
      }
    }
  }
  return [...names].sort();
}

// Every public name (aliases included) sits on one line of the package index, next to its file.
function fileByName() {
  const index = fs.readFileSync(path.join(LUCIDE_ESM, 'lucide-react-native.js'), 'utf8');
  const map = new Map();
  for (const [, exported, file] of index.matchAll(/^export \{([^}]*)\} from '(\.\/icons\/[^']+)'/gm)) {
    for (const part of exported.split(',')) map.set(part.trim().split(/\s+as\s+/).pop(), file);
  }
  return map;
}

function generate() {
  const files = fileByName();
  const lines = usedIcons().map(name => {
    const file = files.get(name);
    if (!file) throw new Error(`lucide-react-native has no icon named "${name}"`);
    const target = path.join(LUCIDE_ESM, file).replace(/\\/g, '/');
    return `export { default as ${name} } from ${JSON.stringify(target)};`;
  });
  const content = `// Generated by scripts/lucide-shim.js — do not edit.\n${lines.join('\n')}\n`;
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, 'utf8') : null;
  if (current !== content) fs.writeFileSync(OUTPUT, content);
  return OUTPUT;
}

module.exports = { generate };
